let s = string.as_str();
let n = s.len();
// Find the longest palindromic suffix
let mut longest_pal_suffix_len = 0;
for i in 0..n {
    // Check if substring s[i..n] is palindrome
    let mut left = i;
    let mut right = n - 1;
    let mut is_pal = true;
    while left < right {
        if s[left..] != s[right..] {
            is_pal = false;
            break;
        }
        left += 1;
        right -= 1;
    }
    if is_pal {
        longest_pal_suffix_len = n - i;
        break;
    }
}
// Build the result
let prefix_len = n - longest_pal_suffix_len;
let prefix = &s[..prefix_len];
let mut result = string.clone();
// Append reverse of prefix
for c in prefix.chars().rev() {
    result.push(c);
}
result

